#ifndef AGENDA_H
#define AGENDA_H

#define MAX 10
#define LARGO 20

typedef enum {
  OK,
  AGENDA_LLENA,
  NOMBRE_REPETIDO,
  NO_ENCONTRADO
} TResultado;

typedef struct {
  char nombres[MAX][LARGO];
  unsigned long telefonos[MAX];
  int cantidad;
} TAgenda;

void inicializar(TAgenda *a);
int total(TAgenda a);
TResultado agregar(TAgenda *a, char nombre[], unsigned long telefono);
TResultado buscar(TAgenda a, char nombre[], unsigned long *telefono);

#endif

#include <string.h>
#include "agenda.h"

void inicializar(TAgenda *a) {
  a->cantidad = 0;
}

int total(TAgenda a) {
  return a.cantidad;
}

TResultado agregar(TAgenda *a, char nombre[], unsigned long telefono) {
  for (int i = 0; i < a->cantidad; i++) {
    if (strcmp(a->nombres[i], nombre) == 0) {
      return NOMBRE_REPETIDO;
    }
  }
  if (a->cantidad == MAX) {
    return AGENDA_LLENA;
  }
  strcpy(a->nombres[a->cantidad], nombre);
  a->telefonos[a->cantidad] = telefono;
  a->cantidad = a->cantidad + 1;
  return OK;
}

TResultado buscar(TAgenda a, char nombre[], unsigned long *telefono) {
  for (int i = 0; i < a.cantidad; i++) {
    if (strcmp(a.nombres[i], nombre) == 0) {
      *telefono = a.telefonos[i];
      return OK;
    }
  }
  return NO_ENCONTRADO;
}

