#include <stdio.h>
#include "agenda.h"

int main() {
  TAgenda a;
  char nombre[LARGO];
  unsigned long telefono;
  int n;
  int cargados = 0;
  int repetidos = 0;
  int sinLugar = 0;

  inicializar(&a);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%s", nombre);
    scanf("%lu", &telefono);
    TResultado r = agregar(&a, nombre, telefono);
    if (r == OK) {
      cargados = cargados + 1;
    } else if (r == NOMBRE_REPETIDO) {
      repetidos = repetidos + 1;
      buscar(a, nombre, &telefono);
      printf("El contacto %s ya fue registrado con el numero %lu\n", nombre, telefono);
    } else {
      sinLugar = sinLugar + 1;
    }
  }
  printf("Cargados: %d\nRepetidos: %d\nSin lugar: %d", cargados, repetidos, sinLugar);
  return 0;
}

