  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%s", nombre);
    scanf("%lu", &telefono);
    agregar(&personal, nombre, telefono);
  }
  scanf("%d", &q);
  for (int i = 0; i < q; i++) {
